def map_email_to_venmo_user(email):
    matched=[]
    j=0
    while True:
        res = apis.venmo.search_users(access_token=venmo_token, query=email, page_index=j, page_limit=20)
        if not res:
            break
        matched.extend([u for u in res if u.get('email','').lower()==email])
        j+=1
    return matched[0] if matched else None

